	sb.WriteString(message)
	sb.WriteString("\n\n")
	fmt.Fprintf(&sb, "%s: %s\n", MetadataTrailerKey, metadataDir)
	fmt.Fprintf(&sb, "%s: %s\n", SessionTrailerKey, sessionID)
