+		}
+		idStr := strings.TrimSpace(value)
+		if seen[idStr] {
+			continue
+		}
+		cpID, err := checkpointID.NewCheckpointID(idStr)
+		if err != nil {
+			continue
+		}
+		seen[idStr] = true
+		ids = append(ids, cpID)
+	}
+	return ids
